// ---------------------------------------------------------------------------
// Origin substitution
// ---------------------------------------------------------------------------
//
// Same PORT throughout every token -- only the HOSTNAME varies. `localhost` and
// `127.0.0.1` are distinct hostnames to every URL-policy implementation and both
// resolve everywhere, so cross-origin / subdomain / external-link fixtures ship
// with zero DNS exposure for the two primary tokens. A different port would be
// wrong here: these fixtures must differ in host with the port held constant, or
// they would pass for the wrong reason.

/// Per-listener origin tokens, resolved once when that listener starts and
/// substituted into every response it serves.
#[derive(Clone, Debug)]
struct Origins {
    /// `{{mock_origin}}` -> `http://127.0.0.1:<port>`, this same listener.
    origin: String,
    /// `{{mock_alt_origin}}` -> `http://<alt_host_base>:<port>`, this same listener
    /// under a different hostname (`<alt_host_base>` defaults to `localhost`; see
    /// [`alt_host_base_from_env`]).
    alt_origin: String,
    /// `{{mock_sub_origin}}` -> `http://sub.<alt_host_base>:<port>`, this same
    /// listener under a subdomain of the alternate hostname.
    sub_origin: String,
    /// `{{mock_foreign_origin}}` -> `http://127.0.0.2:<port>`. Deliberately NOT
    /// bound by any listener: a connection here refuses, which is the correct
    /// outcome for a fixture asserting "genuinely external, must not be fetched".
    foreign_origin: String,
}

impl Origins {
    /// The four `(token, value)` pairs substituted into served content.
    fn token_pairs(&self) -> [(&'static str, &str); 4] {
        [
            ("{{mock_origin}}", self.origin.as_str()),
            ("{{mock_alt_origin}}", self.alt_origin.as_str()),
            ("{{mock_sub_origin}}", self.sub_origin.as_str()),
            ("{{mock_foreign_origin}}", self.foreign_origin.as_str()),
        ]
    }

    /// Substitute origin tokens into a header value (e.g. `Location`, `Refresh`).
    fn substitute_str(&self, value: &str) -> String {
        let mut out = value.to_string();
        for (token, replacement) in self.token_pairs() {
            out = out.replace(token, replacement);
        }
        out
    }

    /// Substitute origin tokens into response body bytes.
    ///
    /// Works at the byte level rather than through `String`/UTF-8 conversion: a
    /// binary fixture body (an image, a compressed payload) that happens not to be
    /// valid UTF-8 must pass through untouched, and a lossy UTF-8 round-trip would
    /// silently corrupt it even when it contains no token at all.
    fn substitute_bytes(&self, bytes: Vec<u8>) -> Vec<u8> {
        let mut current = bytes;
        for (token, replacement) in self.token_pairs() {
            current = replace_all_bytes(&current, token.as_bytes(), replacement.as_bytes());
        }
        current
    }
}

/// Byte-level substring replace. Used instead of a `String`-based `.replace()` so
/// binary bodies without a UTF-8-valid representation are never touched by a lossy
/// conversion (see [`Origins::substitute_bytes`]).
fn replace_all_bytes(haystack: &[u8], needle: &[u8], replacement: &[u8]) -> Vec<u8> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return haystack.to_vec();
    }
    let mut out = Vec::with_capacity(haystack.len());
    let mut index = 0;
    while index < haystack.len() {
        if haystack[index..].starts_with(needle) {
            out.extend_from_slice(replacement);
            index += needle.len();
        } else {
            out.push(haystack[index]);
            index += 1;
        }
    }
    out
}

/// The base hostname `{{mock_alt_origin}}` resolves directly to and `{{mock_sub_origin}}`
/// resolves against with a `sub.` prefix, e.g. `sub.localhost` for the default base
/// `localhost`. Configurable via `ALEF_MOCK_ALT_HOST` (the env var every harness spawn site
/// sets from a consumer's `[crates.e2e] alt_host` config before launching this binary),
/// falling back to `"localhost"` when unset or empty.
fn alt_host_base_from_env() -> String {
    std::env::var("ALEF_MOCK_ALT_HOST")
        .ok()
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "localhost".to_string())
}

/// RFC 6761 makes `*.localhost` resolve to loopback, and that holds on macOS, glibc
/// >= 2.36 / systemd-resolved, and Windows 10 1803+ -- but NOT on musl/Alpine or
/// minimal containers. Probing here means a subdomain fixture fails with a DNS error
/// naming the alias on those platforms, instead of an inscrutable 404 from a listener
/// nothing is actually bound to.
fn sub_host_resolves_to_loopback(sub_host: &str) -> bool {
    use std::net::ToSocketAddrs;
    match (sub_host, 0u16).to_socket_addrs() {
        Ok(addrs) => {
            let mut resolved_any = false;
            for addr in addrs {
                resolved_any = true;
                if !addr.ip().is_loopback() {
                    return false;
                }
            }
            resolved_any
        }
        Err(_) => false,
    }
}

/// Choose the real sub-host or a poison host, given whether `sub_host` was already
/// found to resolve to loopback. Split out from [`resolve_origins`] so the branch
/// itself -- not the platform-dependent DNS probe that feeds it -- is directly
/// testable with a known boolean instead of a real (and platform-variable) lookup.
/// `.invalid` is RFC 2606-reserved and never resolvable, so a poisoned
/// `{{mock_sub_origin}}` fails loudly (a DNS error naming the alias) instead of
/// silently 404ing.
fn sub_origin_or_poison(sub_host: &str, port: u16, resolves_to_loopback: bool) -> String {
    if resolves_to_loopback {
        return format!("http://{sub_host}:{port}");
    }
    eprintln!(
        "mock-server: {sub_host} does not resolve to loopback on this platform (musl/Alpine \
         and minimal containers commonly lack *.localhost support); substituting a poison \
         origin so {{{{mock_sub_origin}}}} fixtures fail with a clear DNS error instead of a \
         silent 404"
    );
    format!("http://alef-unresolvable-alt-host.invalid:{port}")
}

/// Resolve the origin set for a listener bound to `port`.
fn resolve_origins(port: u16) -> Origins {
    let alt_host_base = alt_host_base_from_env();
    let sub_host = format!("sub.{alt_host_base}");
    let resolves_to_loopback = sub_host_resolves_to_loopback(&sub_host);
    Origins {
        origin: format!("http://127.0.0.1:{port}"),
        alt_origin: format!("http://{alt_host_base}:{port}"),
        sub_origin: sub_origin_or_poison(&sub_host, port, resolves_to_loopback),
        foreign_origin: format!("http://127.0.0.2:{port}"),
    }
}

// ---------------------------------------------------------------------------
// Request counter
// ---------------------------------------------------------------------------
//
// Exposes three control endpoints so e2e suites can assert how many requests a
// fixture actually received, without pulling a JSON parser into 21 language
// harnesses:
//   GET  /__alef/requests/total?prefix=<p>       -> decimal count, text/plain
//   GET  /__alef/requests/one?key=<METHOD>%20<p> -> decimal count, text/plain
//   POST /__alef/requests/reset?prefix=<p>       -> 204, no body
//
// Control requests are matched and answered BEFORE route lookup, and are never
// counted themselves.

/// Counts are keyed on the REQUEST path as received, not the matched route's
/// registered (possibly-prefix) path -- both servers here prefix-match routes, so
/// keying on the route path would collapse e.g. `/fixtures/x/a` and `/fixtures/x/b`
/// into a single bucket and make per-path counts meaningless.
static REQUEST_COUNTS: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<(String, String), u64>>> =
    std::sync::OnceLock::new();

fn request_counts() -> &'static std::sync::Mutex<std::collections::HashMap<(String, String), u64>> {
    REQUEST_COUNTS.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Record one request for `(method, path)`. Callers must invoke this for every
/// non-control request, before route lookup, so redirects and 404s are counted too.
fn record_request(method: &str, path: &str) {
    let mut counts = request_counts()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    *counts.entry((method.to_string(), path.to_string())).or_insert(0) += 1;
}

/// Sum of counts across every `(method, path)` key whose path starts with `prefix`.
/// An empty prefix (the parameter was absent) matches every key.
fn total_requests_for_prefix(prefix: &str) -> u64 {
    let counts = request_counts()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    counts
        .iter()
        .filter(|((_, path), _)| path.starts_with(prefix))
        .map(|(_, count)| *count)
        .sum()
}

/// Count for one exact `"<METHOD> <path>"` key. Returns 0 for a malformed or unseen key.
fn count_for_key(key: &str) -> u64 {
    let Some((method, path)) = key.split_once(' ') else {
        return 0;
    };
    let counts = request_counts()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    counts
        .get(&(method.to_string(), path.to_string()))
        .copied()
        .unwrap_or(0)
}

/// Remove every counted key whose path starts with `prefix`. An empty prefix clears
/// every key, matching `total_requests_for_prefix`'s empty-prefix behavior.
fn reset_requests_for_prefix(prefix: &str) {
    let mut counts = request_counts()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    counts.retain(|(_, path), _| !path.starts_with(prefix));
}

/// Minimal `application/x-www-form-urlencoded`-style percent-decoder for query values.
/// Query strings here only ever carry a plain path (`prefix=/fixtures/x`) or a
/// `"<METHOD> <path>"` pair (`key=GET%20/fixtures/x`), so this only needs to handle
/// `%XX` escapes and `+` for space -- not full RFC 3986 generality.
fn percent_decode(input: &str) -> String {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'%' if index + 2 < bytes.len() => {
                let hex = std::str::from_utf8(&bytes[index + 1..index + 3]).ok();
                match hex.and_then(|h| u8::from_str_radix(h, 16).ok()) {
                    Some(value) => {
                        out.push(value);
                        index += 3;
                    }
                    None => {
                        out.push(bytes[index]);
                        index += 1;
                    }
                }
            }
            b'+' => {
                out.push(b' ');
                index += 1;
            }
            other => {
                out.push(other);
                index += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// Look up a single query-string parameter by name, percent-decoding its value.
fn query_param(query: Option<&str>, name: &str) -> Option<String> {
    let query = query?;
    for pair in query.split('&') {
        let mut parts = pair.splitn(2, '=');
        let key = parts.next()?;
        if key == name {
            return Some(percent_decode(parts.next().unwrap_or("")));
        }
    }
    None
}

/// Build a `text/plain` response carrying a bare decimal integer -- deliberately not
/// JSON, so every one of 21 language e2e harnesses can read a counter with "GET a URL,
/// trim, parse an int" instead of pulling in a JSON parser for one number.
fn plain_text_response(status: StatusCode, body: String) -> Response {
    Response::builder()
        .status(status)
        .header("content-type", "text/plain")
        .body(Body::from(body))
        .unwrap()
        .into_response()
}

/// Handle a control-plane request under `/__alef/requests/*`. Returns `None` for any
/// other method/path so the caller falls through to normal route handling.
fn handle_request_counter_control(method: &str, path: &str, query: Option<&str>) -> Option<Response> {
    match (method, path) {
        ("GET", "/__alef/requests/total") => {
            let prefix = query_param(query, "prefix").unwrap_or_default();
            Some(plain_text_response(
                StatusCode::OK,
                total_requests_for_prefix(&prefix).to_string(),
            ))
        }
        ("GET", "/__alef/requests/one") => {
            let key = query_param(query, "key").unwrap_or_default();
            Some(plain_text_response(StatusCode::OK, count_for_key(&key).to_string()))
        }
        ("POST", "/__alef/requests/reset") => {
            let prefix = query_param(query, "prefix").unwrap_or_default();
            reset_requests_for_prefix(&prefix);
            Some(
                Response::builder()
                    .status(StatusCode::NO_CONTENT)
                    .body(Body::empty())
                    .unwrap()
                    .into_response(),
            )
        }
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Route table
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
struct MockRoute {
    status: u16,
    body: Vec<u8>,
    /// Whether this route serves a streaming SSE response.
    /// True even when `stream_chunks` is empty (e.g. an empty stream still sends
    /// `data: [DONE]\n\n` with the correct `content-type: text/event-stream` header).
    is_streaming: bool,
    stream_chunks: Vec<String>,
    headers: Vec<(String, String)>,
    /// Optional artificial delay applied before the handler returns. When set,
    /// the handler `tokio::time::sleep`s for this many milliseconds before
    /// constructing the response — used by timeout-error fixtures to force
    /// client-side request timeouts.
    delay_ms: Option<u64>,
}

type RouteTable = Arc<HashMap<String, MockRoute>>;

/// Per-listener router state: the shared server and each per-fixture origin-root
/// server each get their own `RouteTable` and their own `Origins` (the latter
/// resolved from that listener's own bound port -- see `origins.rs`).
#[derive(Clone)]
struct AppState {
    routes: RouteTable,
    origins: Origins,
}

// ---------------------------------------------------------------------------
// Axum handler
// ---------------------------------------------------------------------------

async fn handle_request(State(state): State<AppState>, req: Request<Body>) -> Response {
    let method = req.method().as_str().to_uppercase();
    let path = req.uri().path().to_owned();
    let query = req.uri().query().map(str::to_owned);

    // Control requests are answered before route lookup and are never counted.
    if let Some(response) = handle_request_counter_control(&method, &path, query.as_deref()) {
        return response;
    }
    record_request(&method, &path);

    let routes = &state.routes;

    // Try exact match first
    if let Some(route) = routes.get(&path) {
        if let Some(delay_ms) = route.delay_ms {
            tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
        }
        return serve_route(route, &state.origins);
    }

    // Try prefix match: find a route that is a prefix of the request path
    // This allows /fixtures/basic_chat/v1/chat/completions to match /fixtures/basic_chat
    for (route_path, route) in routes.iter() {
        if path.starts_with(route_path) && (path.len() == route_path.len() || path.as_bytes()[route_path.len()] == b'/')
        {
            if let Some(delay_ms) = route.delay_ms {
                tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
            }
            return serve_route(route, &state.origins);
        }
    }

    // Fall back to serving a raw test document from the docs dir, so HTTP URL
    // fixtures that reference relative file paths resolve against test_documents.
    if let Some(response) = serve_test_document(&path) {
        return response;
    }

    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .body(Body::from(format!("No mock route for {path}")))
        .unwrap()
        .into_response()
}

fn serve_route(route: &MockRoute, origins: &Origins) -> Response {
    let status = StatusCode::from_u16(route.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);

    if route.is_streaming {
        // Note: stream_chunks may be empty for an empty-stream fixture; we still emit
        // `data: [DONE]\n\n` with the correct SSE headers so clients do not hang.
        let mut sse = String::new();
        for chunk in &route.stream_chunks {
            sse.push_str("data: ");
            sse.push_str(&origins.substitute_str(chunk));
            sse.push_str("\n\n");
        }
        sse.push_str("data: [DONE]\n\n");

        let mut builder = Response::builder()
            .status(status)
            .header("content-type", "text/event-stream")
            .header("cache-control", "no-cache");
        for (name, value) in &route.headers {
            builder = builder.header(name, origins.substitute_str(value));
        }
        return builder.body(Body::from(sse)).unwrap().into_response();
    }

    // Substitute origin tokens before content-type sniffing and encoding, so a fixture
    // whose body is entirely `{{mock_origin}}`-style content still sniffs correctly.
    let body_bytes = origins.substitute_bytes(route.body.clone());

    // Only set the default content-type if the fixture does not override it.
    // Inspect the first non-whitespace byte to detect JSON vs binary vs plain text.
    let has_content_type = route.headers.iter().any(|(k, _)| k.to_lowercase() == "content-type");
    let mut builder = Response::builder().status(status);
    if !has_content_type {
        let first_nonws = body_bytes
            .iter()
            .find(|&&b| b != b' ' && b != b'\t' && b != b'\n' && b != b'\r');
        let default_ct = match first_nonws {
            Some(&b'{') | Some(&b'[') => "application/json",
            _ => "text/plain",
        };
        builder = builder.header("content-type", default_ct);
    }
    // A fixture that declares `content-encoding` gets a body actually encoded that way --
    // gzip and br. br is not optional coverage: a consumer with a brotli compression
    // fixture is the first thing this hard error meets, and a panic here kills the server
    // for every later test in the suite, not just the compression one. This server used to strip the header and serve plain bytes instead, which was
    // safe but left every client-side decompression branch unreachable in every suite --
    // so a compression regression in any binding's HTTP surface could not fail a single
    // test. An unsupported encoding is a hard error rather than a
    // silent fallback to an unencoded body: serving plain bytes under a content-encoding
    // header is exactly the breakage the old strip existed to avoid, and a fixture asking
    // for an encoding this server cannot produce is a fixture bug that should be loud.
    let declared_encoding = route
        .headers
        .iter()
        .find(|(name, _)| name.to_lowercase() == "content-encoding")
        .map(|(_, value)| value.as_str());
    let response_body = match declared_encoding {
        None | Some("<<absent>>") => body_bytes.clone(),
        Some("gzip") => {
            let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
            encoder.write_all(&body_bytes).expect("mock-server: gzip encode failed");
            encoder.finish().expect("mock-server: gzip finish failed")
        }
        Some("br") => {
            let mut encoded = Vec::new();
            brotli::BrotliCompress(
                &mut body_bytes.as_slice(),
                &mut encoded,
                &brotli::enc::BrotliEncoderParams::default(),
            )
            .expect("mock-server: brotli encode failed");
            encoded
        }
        Some(other) => panic!(
            "mock-server: fixture declares content-encoding {other:?}, which this server \
             cannot produce (only gzip and br are supported). Serving an unencoded body under \
             that header would make clients fail to decode."
        ),
    };
    for (name, value) in &route.headers {
        // The <<absent>> sentinel means this header must NOT be present in the
        // real server response — do not emit it from the mock server either.
        if value == "<<absent>>" {
            continue;
        }
        // Replace the <<uuid>> sentinel with a real UUID v4 so clients can
        // assert the header value matches the UUID pattern.
        if value == "<<uuid>>" {
            let uuid = format!(
                "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
                rand_u32(),
                rand_u16(),
                rand_u16() & 0x0fff,
                (rand_u16() & 0x3fff) | 0x8000,
                rand_u48(),
            );
            builder = builder.header(name, uuid);
            continue;
        }
        builder = builder.header(name, origins.substitute_str(value));
    }
    let body = response_body_with_headers(&route.headers, response_body);
    builder.body(body).unwrap().into_response()
}

/// Generate a pseudo-random u32 using the current time nanoseconds.
fn rand_u32() -> u32 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let ns = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.subsec_nanos())
        .unwrap_or(0);
    ns ^ (ns.wrapping_shl(13)) ^ (ns.wrapping_shr(17))
}

fn rand_u16() -> u16 {
    (rand_u32() & 0xffff) as u16
}

fn rand_u48() -> u64 {
    ((rand_u32() as u64) << 16) | (rand_u16() as u64)
}

fn response_body_with_headers(headers: &[(String, String)], bytes: Vec<u8>) -> Body {
    let declared_length = headers
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, value)| value.parse::<u64>().ok());
    if declared_length.is_none_or(|length| length <= bytes.len() as u64) {
        return Body::from(bytes);
    }

    // Exact-sized bodies make Hyper reject intentional Content-Length mismatches
    // before writing headers. Stream the bytes with an unknown size, then yield
    // before terminating so the client observes a truncated body, not a connection
    // failure before the response. The delay begins only after the bytes are polled.
    use tokio_stream::StreamExt;
    const TRUNCATED_BODY_CLOSE_DELAY: std::time::Duration = std::time::Duration::from_millis(50);
    let partial = tokio_stream::once(Ok::<_, std::io::Error>(bytes));
    let termination = tokio_stream::once(()).then(|()| async {
        tokio::time::sleep(TRUNCATED_BODY_CLOSE_DELAY).await;
        Err(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "fixture response body truncated",
        ))
    });
    Body::from_stream(partial.chain(termination))
}

// ---------------------------------------------------------------------------
// Fixture loading
// ---------------------------------------------------------------------------

/// The four origin-substitution placeholders `Origins::token_pairs` resolves at serve time (see
/// origins.rs). A fixture whose body or header values carry one needs a dedicated per-fixture
/// listener for the same reason as the origin-root triggers below: the client is told to follow a
/// full URL, and the shared `/fixtures/<id>`-namespaced table has no route for the path resolved
/// against it. ~keep
const ORIGIN_SUBSTITUTION_TOKENS: [&str; 4] = [
    "{{mock_origin}}",
    "{{mock_alt_origin}}",
    "{{mock_sub_origin}}",
    "{{mock_foreign_origin}}",
];

/// True if `value` contains one of [`ORIGIN_SUBSTITUTION_TOKENS`] verbatim.
fn contains_origin_substitution_token(value: &str) -> bool {
    ORIGIN_SUBSTITUTION_TOKENS.iter().any(|token| value.contains(token))
}

/// Intermediate fixture-loading result: shared route table plus per-fixture origin-root data.
struct LoadedRoutes {
    /// Routes namespaced under /fixtures/<id> for the shared listener.
    shared: HashMap<String, MockRoute>,
    /// For each fixture that has origin-root routes: fixture_id → route table at origin root.
    per_fixture: HashMap<String, HashMap<String, MockRoute>>,
}

fn load_routes(fixtures_dir: &Path) -> LoadedRoutes {
    let mut shared = HashMap::new();
    let mut per_fixture: HashMap<String, HashMap<String, MockRoute>> = HashMap::new();
    load_routes_recursive(fixtures_dir, fixtures_dir, &mut shared, &mut per_fixture);
    LoadedRoutes { shared, per_fixture }
}

fn load_routes_recursive(
    dir: &Path,
    fixtures_root: &Path,
    shared: &mut HashMap<String, MockRoute>,
    per_fixture: &mut HashMap<String, HashMap<String, MockRoute>>,
) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) => {
            eprintln!("warning: cannot read directory {}: {err}", dir.display());
            return;
        }
    };

    let mut paths: Vec<_> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    paths.sort();

    for path in paths {
        if path.is_dir() {
            load_routes_recursive(&path, fixtures_root, shared, per_fixture);
        } else if path.extension().is_some_and(|ext| ext == "json") {
            let filename = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            if filename == "schema.json" || filename.starts_with('_') {
                continue;
            }
            let content = match std::fs::read_to_string(&path) {
                Ok(c) => c,
                Err(err) => {
                    eprintln!("warning: cannot read {}: {err}", path.display());
                    continue;
                }
            };
            let fixtures: Vec<Fixture> = if content.trim_start().starts_with('[') {
                match serde_json::from_str(&content) {
                    Ok(v) => v,
                    Err(err) => {
                        eprintln!("warning: cannot parse {}: {err}", path.display());
                        continue;
                    }
                }
            } else {
                match serde_json::from_str::<Fixture>(&content) {
                    Ok(f) => vec![f],
                    Err(err) => {
                        eprintln!("warning: cannot parse {}: {err}", path.display());
                        continue;
                    }
                }
            };

            for fixture in fixtures {
                let resolved_routes = fixture.as_routes(fixtures_root);
                // A fixture needs origin-root routing if it serves an origin-root discovery path,
                // or if it returns content that makes the client under test request another
                // origin-root path from the same fixture.
                let has_intra_fixture_redirect = resolved_routes.iter().any(|r| {
                    // 3xx with relative Location header
                    let location_redirect = (300..400).contains(&r.response.status)
                        && r.response
                            .headers
                            .iter()
                            .any(|(name, value)| name.eq_ignore_ascii_case("location") && value.starts_with('/'));
                    // Refresh header with url=/...
                    let refresh_redirect = r.response.headers.iter().any(|(name, value)| {
                        if !name.eq_ignore_ascii_case("refresh") {
                            return false;
                        }
                        let lower = value.to_ascii_lowercase();
                        lower
                            .find("url=")
                            .map(|idx| value[idx + 4..].trim_start().starts_with('/'))
                            .unwrap_or(false)
                    });
                    // HTML meta-refresh tag pointing to /...
                    let body_lower_lossy = String::from_utf8_lossy(&r.body_bytes).to_ascii_lowercase();
                    let meta_refresh = body_lower_lossy
                        .split("http-equiv=\"refresh\"")
                        .nth(1)
                        .and_then(|s| s.split("content=").nth(1))
                        .map(|s| {
                            let trimmed = s.trim_start_matches(['"', '\'']);
                            trimmed.contains("url=/")
                        })
                        .unwrap_or(false);
                    location_redirect || refresh_redirect || meta_refresh
                });
                // Inline HTML anchors that target host-absolute paths (`<a href="/page1">`)
                // also require a dedicated listener because clients resolve these against the
                // URL host, not the `/fixtures/<id>/` namespace.
                let has_inline_host_link = resolved_routes.iter().any(|r| {
                    let body_lossy = String::from_utf8_lossy(&r.body_bytes);
                    body_lossy.contains("href=\"/") || body_lossy.contains("href='/")
                });
                // A body or header value carrying an origin-substitution token (see
                // ORIGIN_SUBSTITUTION_TOKENS above) resolves to a host-absolute URL, so it needs
                // the same dedicated listener as an intra-fixture redirect or inline host link.
                let has_origin_substitution_token = resolved_routes.iter().any(|r| {
                    let body_lossy = String::from_utf8_lossy(&r.body_bytes);
                    contains_origin_substitution_token(&body_lossy)
                        || r.response
                            .headers
                            .iter()
                            .any(|(_, value)| contains_origin_substitution_token(value))
                });
                let has_host_root = has_intra_fixture_redirect
                    || has_inline_host_link
                    || has_origin_substitution_token
                    || resolved_routes.iter().any(|r| is_host_root_path(&r.original_path));

                for resolved in resolved_routes {
                    let is_streaming = resolved.response.stream_chunks.is_some();
                    let stream_chunks = resolved
                        .response
                        .stream_chunks
                        .unwrap_or_default()
                        .into_iter()
                        .map(|c| match c {
                            serde_json::Value::String(s) => s,
                            other => serde_json::to_string(&other).unwrap_or_default(),
                        })
                        .collect();
                    let mut headers: Vec<(String, String)> = resolved.response.headers.into_iter().collect();
                    headers.sort_by(|a, b| a.0.cmp(&b.0));

                    let mock_route = MockRoute {
                        status: resolved.response.status,
                        body: resolved.body_bytes,
                        is_streaming,
                        stream_chunks,
                        headers,
                        delay_ms: resolved.response.delay_ms,
                    };

                    // Insert into the shared namespaced table, but skip origin-root paths
                    // (`/robots*`, `/sitemap*`) because those collide across fixtures and the
                    // last-write-wins behavior makes test results depend on fixture-load
                    // order. Origin-root routes are served only by the dedicated per-fixture
                    // listener spawned below for fixtures that declare them.
                    if !is_host_root_path(&resolved.original_path) {
                        shared.insert(resolved.path.clone(), mock_route.clone());
                    }

                    // For fixtures with origin-root routes, also build a per-fixture table
                    // where routes are mounted at their original (un-namespaced) paths.
                    if has_host_root {
                        per_fixture
                            .entry(fixture.id.clone())
                            .or_default()
                            .insert(resolved.original_path.clone(), mock_route);
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

#[tokio::main]
async fn main() {
    let fixtures_dir_arg = std::env::args().nth(1).unwrap_or_else(|| "../../fixtures".to_string());
    let fixtures_dir = Path::new(&fixtures_dir_arg);

    // Resolve the test-documents corpus served as an HTTP fallback. Prefer the
    // explicit env var; otherwise use the `test_documents` sibling of the fixtures dir.
    let docs_dir = std::env::var_os("ALEF_TEST_DOCUMENTS_DIR")
        .map(PathBuf::from)
        .or_else(|| fixtures_dir.parent().map(|parent| parent.join("test_documents")))
        .filter(|dir| dir.is_dir());
    let _ = DOCS_DIR.set(docs_dir);

    let loaded = load_routes(fixtures_dir);
    eprintln!(
        "mock-server: loaded {} shared routes from {}",
        loaded.shared.len(),
        fixtures_dir.display()
    );

    // Bind first, then resolve origins from the actual bound port -- each listener
    // substitutes `{{mock_origin}}`-style tokens using its OWN port, so a fixture's
    // self-referencing links always point back at the listener that served them.
    let shared_listener = TcpListener::bind("127.0.0.1:0")
        .await
        .expect("mock-server: failed to bind shared port");
    let shared_addr: SocketAddr = shared_listener
        .local_addr()
        .expect("mock-server: failed to get shared local addr");
    let shared_table: RouteTable = Arc::new(loaded.shared);
    let shared_state = AppState {
        routes: shared_table,
        origins: resolve_origins(shared_addr.port()),
    };
    let shared_app = Router::new().fallback(handle_request).with_state(shared_state);

    // Per-fixture listeners for origin-root routes.
    // Sorted by fixture_id for deterministic output.
    let mut fixture_ids: Vec<String> = loaded.per_fixture.keys().cloned().collect();
    fixture_ids.sort();

    let mut fixture_urls: HashMap<String, String> = HashMap::new();
    let mut readiness_addrs: Vec<SocketAddr> = Vec::new();
    for fixture_id in &fixture_ids {
        let routes = loaded.per_fixture[fixture_id].clone();
        eprintln!(
            "mock-server: fixture {} has {} origin-root routes",
            fixture_id,
            routes.len()
        );
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("mock-server: failed to bind per-fixture port");
        let addr: SocketAddr = listener
            .local_addr()
            .expect("mock-server: failed to get per-fixture local addr");
        let table: RouteTable = Arc::new(routes);
        let state = AppState {
            routes: table,
            origins: resolve_origins(addr.port()),
        };
        let app = Router::new().fallback(handle_request).with_state(state);
        fixture_urls.insert(fixture_id.clone(), format!("http://{addr}"));
        readiness_addrs.push(addr);
        tokio::spawn(async move {
            axum::serve(listener, app)
                .await
                .expect("mock-server: per-fixture server error");
        });
    }

    // Spawn the shared server before printing — the print is the readiness
    // signal consumers rely on, so the task must be running first.
    readiness_addrs.push(shared_addr);
    tokio::spawn(async move {
        axum::serve(shared_listener, shared_app)
            .await
            .expect("mock-server: shared server error");
    });

    // Poll each listener with a self-connect until it is actually accepting.
    // This eliminates the race where consumers (e.g. Go's http.Get) attempt a
    // connection in the window between the print and the tokio task being
    // scheduled for the first time.
    for addr in &readiness_addrs {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if TcpStream::connect(addr).await.is_ok() {
                break;
            }
            if std::time::Instant::now() >= deadline {
                eprintln!("mock-server: warning: listener {addr} did not become ready within 5s");
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
    }

    // Print the shared URL so the parent process can read it.
    println!("MOCK_SERVER_URL=http://{shared_addr}");

    // Always print MOCK_SERVERS=... (empty `{}` when there are no origin-root
    // fixtures) so parent parsers — which read until they see this sentinel
    // line — never block on a readline that never comes.
    let mut sorted_pairs: Vec<(&String, &String)> = fixture_urls.iter().collect();
    sorted_pairs.sort_by_key(|(k, _)| k.as_str());
    let json_entries: Vec<String> = sorted_pairs
        .iter()
        .map(|(k, v)| format!("\"{}\":\"{}\"", k, v))
        .collect();
    println!("MOCK_SERVERS={{{}}}", json_entries.join(","));

    // Flush stdout explicitly so the parent does not block waiting.
    use std::io::Write;
    std::io::stdout().flush().expect("mock-server: failed to flush stdout");

    // Lifetime: by default block until stdin is closed (the typical
    // parent-controlled subprocess pattern used by Rust/Node/Python/etc. test
    // harnesses that spawn this binary directly). When `MOCK_SERVER_NO_STDIN_WATCH=1`
    // is set, block on Ctrl-C / SIGTERM instead — useful for CI launches that
    // background the process across multiple shell steps (the per-step shell
    // exits and the inherited stdin FD closes, which would otherwise kill the
    // server between steps before the test step runs).
    if std::env::var("MOCK_SERVER_NO_STDIN_WATCH").as_deref() == Ok("1") {
        let _ = tokio::signal::ctrl_c().await;
    } else {
        let stdin = io::stdin();
        let mut lines = stdin.lock().lines();
        while lines.next().is_some() {}
    }
}

// ---------------------------------------------------------------------------
// Test-document HTTP fallback
// ---------------------------------------------------------------------------

/// Directory holding the test-document corpus, resolved once at startup.
static DOCS_DIR: OnceLock<Option<PathBuf>> = OnceLock::new();

/// Map a file extension to the MIME type the extraction core expects for it.
fn content_type_for(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(|e| e.to_str())
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("txt") => "text/plain",
        Some("md") => "text/markdown",
        Some("csv") => "text/csv",
        Some("html" | "htm") => "text/html",
        Some("json") => "application/json",
        Some("xml") => "application/xml",
        Some("pdf") => "application/pdf",
        Some("docx") => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        Some("xlsx") => "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        Some("pptx") => "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        Some("hwpx") => "application/hwp+zip",
        Some("png") => "image/png",
        Some("jpg" | "jpeg") => "image/jpeg",
        Some("gif") => "image/gif",
        Some("zip") => "application/zip",
        _ => "application/octet-stream",
    }
}

/// Resolve `request_path` against the test-documents directory and serve the file
/// if it exists. Returns `None` when no docs dir is configured or the file is
/// missing, so the caller can fall through to a 404.
///
/// Language suites that ingest documents over HTTP (e.g. Node) request
/// `/<rel>/<file>` against the shared server; these paths are not fixture routes,
/// so the router resolves them here against the test-documents directory and
/// serves the bytes with an extension-derived content-type. Suites that pass
/// local file paths (Python, Go, Rust) never hit this.
fn serve_test_document(request_path: &str) -> Option<Response> {
    let docs_dir = DOCS_DIR.get()?.as_ref()?;
    let relative = request_path.trim_start_matches('/');
    if relative.is_empty() {
        return None;
    }
    // Guard against path traversal: reject any `..` component.
    if relative.split('/').any(|segment| segment == "..") {
        return None;
    }
    let candidate = docs_dir.join(relative);
    let bytes = std::fs::read(&candidate).ok()?;
    Some(
        Response::builder()
            .status(StatusCode::OK)
            .header("content-type", content_type_for(&candidate))
            .body(Body::from(bytes))
            .unwrap()
            .into_response(),
    )
}
